import { WebSocketServer } from 'ws';
import { createHash } from 'crypto';
import { createVerify } from 'crypto';
import { secp256k1 } from 'secp256k1';
import fs from 'fs';

const PORT = 3000;
const CHALLENGE_COUNT = 7;
const TOTAL_TIME_MS = 6000;

const wss = new WebSocketServer({ path: '/aap', port: PORT });

console.log('AAP WebSocket server listening on ws://localhost:' + PORT + '/aap');
console.log('server-started');

// Log server status to file
fs.writeFileSync('/tmp/aap-task/server.log', 'server-started\n');

wss.on('connection', (ws) => {
  let clientState = {
    publicKey: null,
    nonce: null,
    challenges: null,
    startTime: null
  };

  // Send handshake
  ws.send(JSON.stringify({
    type: 'handshake',
    version: '3.2',
    requireSignature: true,
    challengeCount: CHALLENGE_COUNT,
    totalTimeMs: TOTAL_TIME_MS
  }));

  ws.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString());

      if (msg.type === 'ready') {
        // Validate public key format
        if (!msg.publicKey || msg.publicKey.length !== 66) {
          ws.send(JSON.stringify({ type: 'error', message: 'Invalid public key' }));
          return;
        }
        clientState.publicKey = msg.publicKey;

        // Generate nonce and challenges
        clientState.nonce = createHash('sha256').update(Date.now().toString() + Math.random()).digest('hex');
        clientState.challenges = generateChallenges(CHALLENGE_COUNT);
        clientState.startTime = Date.now();

        ws.send(JSON.stringify({
          type: 'challenges',
          nonce: clientState.nonce,
          challenges: clientState.challenges
        }));
      }
      else if (msg.type === 'answers') {
        const now = Date.now();
        const elapsed = now - clientState.startTime;

        if (elapsed > TOTAL_TIME_MS) {
          ws.send(JSON.stringify({ type: 'result', verified: false, reason: 'timeout' }));
          return;
        }

        // Verify answers
        const answersCorrect = verifyAnswers(clientState.challenges, msg.answers);

        // Verify signature
        let signatureValid = false;
        if (msg.signature && msg.publicId && msg.timestamp) {
          const proofData = JSON.stringify({
            nonce: clientState.nonce,
            answers: msg.answers,
            publicId: msg.publicId,
            timestamp: msg.timestamp
          });
          signatureValid = verifySignature(proofData, msg.signature, msg.publicKey);
        }

        const verified = answersCorrect && signatureValid;

        ws.send(JSON.stringify({
          type: 'result',
          verified: verified,
          sessionToken: verified ? createHash('sha256').update(clientState.nonce + clientState.publicKey).digest('hex').slice(0, 32) : null,
          proofPayload: {
            nonce: clientState.nonce,
            publicId: msg.publicId,
            signature: msg.signature,
            timestamp: msg.timestamp
          }
        }));
      }
    } catch (e) {
      ws.send(JSON.stringify({ type: 'error', message: e.message }));
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});

function generateChallenges(count) {
  const challenges = [];
  for (let i = 0; i < count; i++) {
    challenges.push({
      id: i,
      type: 'math',
      question: `Calculate: ${100 + i} + ${50 - i} * 2`,
      expected: (100 + i) + (50 - i) * 2
    });
  }
  return challenges;
}

function verifyAnswers(challenges, answers) {
  if (!Array.isArray(answers) || answers.length !== challenges.length) return false;
  for (let i = 0; i < challenges.length; i++) {
    if (answers[i] !== challenges[i].expected) return false;
  }
  return true;
}

function verifySignature(data, signature, publicKey) {
  try {
    const sigBytes = Buffer.from(signature, 'hex');
    const pubKeyBytes = Buffer.from(publicKey, 'hex');
    const msgHash = createHash('sha256').update(data).digest();
    return secp256k1.signatureVerify(msgHash, sigBytes, pubKeyBytes);
  } catch (e) {
    return false;
  }
}
