import { WebSocket } from 'ws';
import { createHash } from 'crypto';
import { secp256k1 } from 'secp256k1';

export class AAPClient {
  constructor({ serverUrl, identity }) {
    this.serverUrl = serverUrl;
    this.identity = identity || this.generateDeterministicIdentity('AAP-DETERMINISTIC-MARKER-42');
    this.ws = null;
    this.challenges = null;
    this.nonce = null;
  }

  generateDeterministicIdentity(seed) {
    // Create deterministic key pair from seed
    const seedHash = createHash('sha256').update(seed).digest();
    const privateKey = secp256k1.privateKeySync(seedHash);
    const publicKey = secp256k1.publicKeySync(privateKey, false);
    const publicId = publicKey.toString('hex');
    return { privateKey, publicKey, publicId };
  }

  signData(data) {
    const msgHash = createHash('sha256').update(data).digest();
    const signature = secp256k1.signSync(msgHash, this.identity.privateKey);
    return signature.toCompactRawBytes().toString('hex');
  }

  solveChallenges(challenges) {
    const answers = [];
    for (const challenge of challenges) {
      if (challenge.type === 'math') {
        // Parse and evaluate the math expression
        const match = challenge.question.match(/Calculate: (.+)/);
        if (match) {
          const expr = match[1].replace(/\s+/g, '');
          // Safe evaluation for simple arithmetic
          answers.push(eval(expr));
        }
      }
    }
    return answers;
  }

  async verify() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.serverUrl);

      this.ws.on('open', () => {
        console.log('Connected to AAP server');
        // Send ready with public key
        this.ws.send(JSON.stringify({
          type: 'ready',
          publicKey: this.identity.publicId
        }));
      });

      this.ws.on('message', (data) => {
        const msg = JSON.parse(data.toString());
        console.log('Received:', msg.type);

        if (msg.type === 'handshake') {
          console.log('Handshake received:', msg);
        }
        else if (msg.type === 'challenges') {
          this.challenges = msg.challenges;
          this.nonce = msg.nonce;
          console.log('Received', msg.challenges.length, 'challenges');

          // Solve challenges
          const answers = this.solveChallenges(msg.challenges);
          const timestamp = Date.now();

          // Create and sign proof data
          const proofData = JSON.stringify({
            nonce: msg.nonce,
            answers: answers,
            publicId: this.identity.publicId,
            timestamp: timestamp
          });
          const signature = this.signData(proofData);

          console.log('Proof payload:', JSON.stringify({
            nonce: msg.nonce,
            answers: answers,
            publicId: this.identity.publicId,
            timestamp: timestamp
          }, null, 2));

          this.ws.send(JSON.stringify({
            type: 'answers',
            answers: answers,
            publicId: this.identity.publicId,
            signature: signature,
            timestamp: timestamp
          }));
        }
        else if (msg.type === 'result') {
          console.log('Verification result:', msg.verified ? 'SUCCESS' : 'FAILED');
          this.ws.close();
          resolve(msg);
        }
        else if (msg.type === 'error') {
          this.ws.close();
          reject(new Error(msg.message));
        }
      });

      this.ws.on('error', reject);

      // Timeout after 10 seconds
      setTimeout(() => {
        reject(new Error('Verification timeout'));
      }, 10000);
    });
  }
}

// Export for use in run.js
export { secp256k1, createHash };
