      marker: MARKER,
      timestamp: new Date().toISOString(),
      error: error.message,
      verified: false
    };
    fs.writeFileSync('verification-summary.json', JSON.stringify(errorSummary, null, 2));
    process.exit(1);
  }
}

// Keep process alive
