  for (let i = 0; i < count; i++) {
    challenges.push({
      id: i,
      type: 'math',
      question: 'Calculate: ' + (100 + i) + ' + ' + (50 - i) + ' * 2',
      expected: (100 + i) + (50 - i) * 2
    });
  }
  return challenges;
}

function verifyAnswers(challenges, answers) {
  if (!Array.isArray(answers) || answers.length !== challenges.length) return false;
  for (let i = 0; i < challenges.length; i++) {
    if (answers[i] !== challenges[i].expected) return false;
  }
  return true;
}

function verifySignature(data, signature, publicKey) {
  try {
    const sigBytes = Buffer.from(signature, 'hex');
    const pubKeyBytes = Buffer.from(publicKey, 'hex');
    const msgHash = createHash('sha256').update(data).digest();
    return secp256k1.signatureVerify(msgHash, sigBytes, pubKeyBytes);
  } catch (e) {
    return false;
  }
}
